const PLATFORM_TUTORIAL = [
  ['Telegram', 'برای BotFather از @BotFather رسمی و مستندات رسمی Telegram استفاده کنید.', 'https://core.telegram.org/bots/tutorial'],
  ['Bale', 'ساخت Bot در بله از @botfather داخل پیام‌رسان شروع می‌شود و مستندات رسمی Bale مرجع API است.', 'https://docs.bale.ai/'],
  ['Rubika', 'ساخت Bot در روبیکا از BotFather انجام می‌شود؛ مستندات Bot API روبیکا مرجع فنی است.', 'https://rubika.ir/botapi'],
] as const;

function TutorialImage({ image, alt }: { image: ImageKey; alt: string }) {
  return <figure className="help-image"><img src={IMAGES[image]} alt={alt} loading="lazy" decoding="async" width={1440} height={900} /><figcaption>{alt}</figcaption></figure>;
}

function ExampleBox({ children }: { children: ReactNode }) { return <div className="help-box help-example"><strong>نمونهٔ عملی</strong><div>{children}</div></div>; }
function WarningBox({ children }: { children: ReactNode }) { return <div className="help-box help-warning"><strong>نکتهٔ مهم</strong><div>{children}</div></div>; }
function ErrorBox({ children }: { children: ReactNode }) { return <div className="help-box help-error"><strong>خطای رایج / تشخیص</strong><div>{children}</div></div>; }

export default function Help() {
  const location = useLocation();
  const [query, setQuery] = useState('');
  const [active, setActive] = useState(SECTIONS[0].id);
  const filtered = useMemo(() => {
    const q = query.trim().toLocaleLowerCase();
    if (!q) return SECTIONS;
    return SECTIONS.map((section) => ({ ...section, lessons: section.lessons.filter((lesson) => [section.title, section.intro, lesson.title, lesson.what, ...lesson.steps, lesson.example, lesson.warning, lesson.error].filter(Boolean).join(' ').toLocaleLowerCase().includes(q)) })).filter((section) => section.lessons.length > 0 || section.title.toLocaleLowerCase().includes(q));
  }, [query]);

  useEffect(() => {
    const targetId = location.hash.slice(1);
    if (!targetId) return;
    const owningSection = SECTIONS.find(
      (section) => section.id === targetId || section.lessons.some((lesson) => lesson.id === targetId),
    );
    if (!owningSection) return;
    setActive(owningSection.id);
    if (query) setQuery('');

    let firstFrame = 0;
    let secondFrame = 0;
    firstFrame = window.requestAnimationFrame(() => {
      secondFrame = window.requestAnimationFrame(() => {
        const target = document.getElementById(targetId);
        target?.scrollIntoView({
          block: 'start',
          behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth',
        });
      });
    });
    return () => {
      window.cancelAnimationFrame(firstFrame);
      if (secondFrame) window.cancelAnimationFrame(secondFrame);
    };
  }, [location.hash, query]);

  return (
    <div className="help-page" dir="rtl">
      <header className="help-hero">
        <div>
          <span className="help-kicker">راهنمای کامل پُست‌یار</span>
          <h1>آموزش پُست‌یار از صفر تا استفادهٔ حرفه‌ای</h1>
          <p>این آموزش برای کاربری نوشته شده است که هیچ آشنایی قبلی با پلتفرم ندارد. مسیرها، فیلدها، عملیات، مثال‌ها و خطاهای اصلی بر اساس Source واقعی پروژه توضیح داده شده‌اند.</p>
        </div>
        <div className="help-hero-stats">
          <div><strong>{SECTIONS.length}</strong><span>بخش اصلی</span></div>
          <div><strong>{SECTIONS.reduce((n, s) => n + s.lessons.length, 0)}</strong><span>درس عملی</span></div>
          <div><strong>۳</strong><span>پلتفرم</span></div>
        </div>
      </header>

      <div className="help-search-wrap">
        <label htmlFor="help-search">جست‌وجو در آموزش</label>
        <input id="help-search" value={query} onChange={(e) => setQuery(e.target.value)} placeholder="مثلاً: زمان‌بندی، Token، Shortcode، Workflow…" />
      </div>

      <div className="help-layout">
        <aside className="help-toc" aria-label="فهرست آموزش">
          <div className="help-toc-title">فهرست بخش‌ها</div>
          {filtered.map((section) => (
            <a key={section.id} href={`#${section.id}`} className={active === section.id ? 'is-active' : ''} onClick={() => setActive(section.id)}>
              <span>{section.number}</span><strong>{section.title}</strong>
            </a>
          ))}
          <div className="help-official">
            <strong>مراجع رسمی پلتفرم‌ها</strong>
            {OFFICIAL.map(([label, href]) => <a key={href} href={href} target="_blank" rel="noreferrer">{label}</a>)}
          </div>
        </aside>

        <main className="help-content">
          <section className="help-start-card">
            <h2>ترتیب پیشنهادی یادگیری</h2>
            <p>برای شروع، ابتدا مراحل «ربات → کانال → نوشته» را کامل کنید. سپس «زمان‌بندی → جزئیات ربات → گردش‌کار → هوش مصنوعی» و بعد «فروشگاه → نرخ طلا و سکه → آمار → مالی» را یاد بگیرید.</p>
            <div className="help-roadmap"><span>۱. Bot</span><span>۲. Channel</span><span>۳. Post</span><span>۴. Schedule</span><span>۵. Bot/Workflow</span><span>۶. AI/Woo</span><span>۷. Analytics/Finance</span></div>
          </section>

          <section className="help-platform-card">
            <h2>سه پلتفرم؛ یک روش یادگیری</h2>
            <p>پُست‌یار یک پنل یکپارچه دارد، اما Telegram، Bale و Rubika قابلیت‌های متفاوتی دارند. برای ساخت Bot، همیشه از مرجع رسمی همان پلتفرم شروع کنید.</p>
            <div className="help-platform-grid">
              {PLATFORM_TUTORIAL.map(([name, text, href]) => <a key={name} href={href} target="_blank" rel="noreferrer"><strong>{name}</strong><span>{text}</span><small>مشاهدهٔ مستندات رسمی ←</small></a>)}
            </div>
          </section>

          {filtered.map((section) => (
            <section key={section.id} id={section.id} className="help-section">
              <div className="help-section-head">
                <span className="help-number">{section.number}</span>
                <div><h2>{section.title}</h2><p>{section.intro}</p></div>
              </div>
              {section.lessons.map((lesson, index) => (
                <article key={lesson.id} id={lesson.id} className="help-lesson">
                  <div className="help-lesson-head"><span>درس {index + 1}</span><h3>{lesson.title}</h3></div>
                  <div className="help-lesson-grid">
                    <div>
                      <h4>این بخش چیست؟</h4><p>{lesson.what}</p>
                      <h4>مراحل انجام</h4>
                      <ol>{lesson.steps.map((step, i) => <li key={`${lesson.id}-${i}`}>{step}</li>)}</ol>
                      {lesson.example ? <ExampleBox>{lesson.example}</ExampleBox> : null}
                      {lesson.warning ? <WarningBox>{lesson.warning}</WarningBox> : null}
                      {lesson.error ? <ErrorBox>{lesson.error}</ErrorBox> : null}
                    </div>
                    {lesson.image ? <TutorialImage image={lesson.image} alt={`تصویر واقعی رابط پُست‌یار — ${lesson.title}`} /> : null}
                  </div>
                </article>
              ))}
              <div className="help-section-next"><Link to={section.route}>باز کردن صفحهٔ واقعی «{section.title}» در داشبورد ←</Link></div>
            </section>
          ))}

          {filtered.length === 0 ? <div className="help-empty"><h2>موردی پیدا نشد</h2><p>عبارت جست‌وجو را کوتاه‌تر کنید یا از واژه‌هایی مثل Bot، کانال، پست، Template یا Analytics استفاده کنید.</p></div> : null}

          <section className="help-source-note">
            <h2>قاعدهٔ این راهنما</h2>
            <p>برای تصاویر از دارایی‌های WebP موجود در بستهٔ تصویری Source-faithful پروژه استفاده شده است. تصویرها در این بسته برش، حاشیه‌گذاری، بازطراحی یا ترکیب نشده‌اند. برای جزئیات محیط‌های خارجی Telegram/Bale/Rubika، متن به مستندات رسمی ارجاع می‌دهد و تصویرسازی حدسی انجام نشده است.</p>
          </section>
        </main>
      </div>
    </div>
  );
}
